******************************************************************************** InitSeg.asm** (C)  Copyright Apple Computer, Inc. 1990* All rights reserved.** by Jim Mensch* 5/16/90** This file is to contain all the code that need only be run once at system startup* this will include	several bootInit functions from some of	the tools, this should free* up a little more memory in the system	for applications to	use.** Files:	include 'all.macros'	include ':::sys.equs.asm'	INCLUDE ':::qd:QDEquates:qd.data.asm'	INCLUDE ':::qd:QDEquates:core.globals1'	INCLUDE ':::qd:QDEquates:core.globals2'	include 'e16.memory'**** Modification History:** Version 1.0   	Mensch** Added QDBootInit** 25-Sep-90	Dave Lyons** Removed check of BigMachine--the patches are unconditional now.** 5-Aug-91	Dave Lyons** Removed patches for DrawCursor and UnDrawCursor.  These were for* letting the SaveHandle be unlocked, which is not implemented; patches* were incompatible with new flickerless-cursor stuff.********************************************************************************	Import eSetPort	Import eSetPortLoc	Import eSetPortRect	Import eSetPortSize	Import eMovePortTo	Import eSetOrigin	Import eHidePen	Import eSetPenState	Import eSetDrawMask	Import ePenNormal	Import eSolidPenPat	Import eSolidBackPat	Import eSolidPattern	Import eSetGrafProcs	Import RectCalls	Import ePPToPort	Import eScrollRect	Import ePaintPixels***	Import BigMachine	Import NewRgnCode	Import NewRectCode	Import FrRect	Import ThisGimmeVersion	Import IPutRgn2	Import IRgnOp2*****************************************************************QDBootInit2	PROC EXPORT** This is called when the QD patch is installed.*** Inputs:*	none** Outputs:*	none** External Refs:	import OrigStdRgn*	and built into PatchMacro.** Entry Points:*	none*	longa on	; mode	longi on*** Change History** 11 Dec 88	Steven Glass** No longer calls InstallSlabPatches.  Instead these are installed* in line. Change History from InstallSlabPatches follows:** 05 Dec 88	Steven Glass** This routine used to save the old StdPoly vector value.  * But no one used it so I remove the save and the storage for* the value.** 08 Dec 88	STeven Glass** Did patching in macro.  Added patches to XSetup, SetSlabAdr,* RotatePat, RotateMask and ExpandMask.** 11 Dec 88	Steven Glass** Added DrawRect, DrawRectB, StdLine and StdRgn.** 2/1/89	Mensch** Added startup shadowing enable and linked in openport * InitPort and shutdown** 3/12/89	Steven Glass** Only patch some routines if machine is big.** 14 Apr 89	Steven Glass** Add the overhead speedup routines to the patch by * patching many entry points and a few internal vectors.*** 01 Jun 89	Steven Glass** Patched the vectored inputs to PRgn, IRgn ... and PRect, IRect...* This made polygons work with all patterns, not just lucky ones.*****************************************************************	MACRO&lab	PATCH &Name	import i&Name&lab	lda #i&Name	sta |&Name+1	lda #>i&Name	sta |&Name+2	MEND	MACRO&lab	StuffTable &Name,&Loc	import &Name&lab	lda #&Name-1	sta >&Loc	lda #^&Name	sta >&Loc+2	MEND	export ConTable320:equConTable320	equ $FE4C3B	export ConTable640:equConTable640	equ $FE503B	phb	pea $E0E0	plb	plb	Patch StdPoly***	lda >BigMachine	;removed 25-Sep-90 DAL***	beql NotBig	Patch DrawConic	Patch XSetup	Patch SetSlabAdr	Patch RotatePat	Patch RotateMask	Patch ExpandMask	Patch DrawRect	Patch DrawRectB	PATCH StdLine	Patch StdRgn	Patch DText	Patch ValidChar	Patch DChar	Patch stdText	Patch CalcDrawStatus; Start 14 Apr 89 Addition	Patch stdRect	patch userpat2ZP	patch portLoc2ZP	patch GetPenPReady	patch GetBackPReady	patch Pen2ZP	patch Back2ZP	patch GetMaskReady;;;	Patch DrawCursor	;removed 5-Aug-91 DAL;;;	Patch UnDrawCursor	;removed 5-Aug-91 DAL	Patch RgnBlt	;26-Mar-91 DAL	import RectCalls	StuffTable FrameRect,RectCalls	StuffTable PaintRect,RectCalls+4	StuffTable EraseRect,RectCalls+8	StuffTable InvertRect,RectCalls+12	StuffTable FillRect,RectCalls+16	StuffTable SetPort,eSetPort	StuffTable SetPortLoc,eSetPortLoc	StuffTable SetPortRect,eSetPortRect	StuffTable SetPortSize,eSetPortSize	StuffTable MovePortTo,eMovePortTo	StuffTable SetOrigin,eSetOrigin	StuffTable HidePen,eHidePen	StuffTable SetPenState,eSetPenState	StuffTable SetDrawMask,eSetDrawMask	; added SEG 13 May 89	StuffTable PenNormal,ePenNormal	StuffTable SolidBackPat,eSolidBackPat	StuffTable SolidPenPat,eSolidPenPat	StuffTable SolidPattern,eSolidPattern	StuffTable SetGrafProcs,eSetGrafProcs; End 14 Apr 89 Addition; Start 13 May 89 Addition	StuffTable PPToPort,ePPToPort	StuffTable PaintPixels,ePaintPixels	StuffTable ScrollRect,eScrollRect; End 13 May 89 Addition; Start 01 Jun 89 Addition	lda #NewRgnCode	sta |v_FrRgn+1	sta |v_PRgn+1	sta |v_ERgn+1	sta |v_IRgn+1	sta |v_FRgn+1	lda #>NewRgnCode	sta |v_FrRgn+2	sta |v_PRgn+2	sta |v_ERgn+2	sta |v_IRgn+2	sta |v_FRgn+2	lda #NewRectCode	sta |v_PRect+1	sta |v_ERect+1	sta |v_IRect+1	sta |v_FRect+1	lda #>NewRectCode	sta |v_PRect+2	sta |v_ERect+2	sta |v_IRect+2	sta |v_FRect+2; set v_FrRect to FrRect instead of the other place; SEG 08 Jun 89	lda #FrRect	sta |v_FrRect+1	lda #>FrRect	sta |v_FrRect+2*** NotBig	PATCH SetupFontInfo	PATCH GetFGS	lda #ThisGimmeVersion	sta |GimmeVersion+1	lda #>ThisGimmeVersion	sta |GimmeVersion+2	lda #iPutRgn2	sta |PutRgn+1	lda #>iPutRgn2	sta |PutRgn+2	lda #iRgnOp2	sta |RgnOp+1	lda #>iRgnOp2	sta |RgnOp+2	Patch ShieldCursor	plb	rtl	EndP	End